#!/usr/bin/env bash
# This shell is used to create a simpler way to run the application. The code was mostly
# generated by AI initially, it was then reviewed by the team members and verified that it works correctly.

set -euo pipefail
umask 077

root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
cd "$root"

jdk_bin="${JAVA_HOME:+$JAVA_HOME/bin/}"
if [[ -n "${JAVA_HOME:-}" ]] && command -v cygpath >/dev/null 2>&1; then
  jdk_bin="$(cygpath -u "$JAVA_HOME")/bin/"
fi
java="${jdk_bin}java"
javac="${jdk_bin}javac"
keytool="${jdk_bin}keytool"
if ! version="$("$javac" -version 2>&1)" \
    || [[ ! "${version%$'\r'}" =~ ^javac\ 25([.+-]|$) ]]; then
  echo "The local demo needs JDK 25. Set JAVA_HOME to its installation and run this again." >&2
  exit 1
fi

port="${SMART_HOME_DEMO_PORT:-5000}"
if [[ ! "$port" =~ ^[0-9]{1,5}$ ]] || ((10#$port < 1 || 10#$port > 65535)); then
  echo "SMART_HOME_DEMO_PORT must be between 1 and 65535." >&2
  exit 1
fi
# Keep credentials and address overrides from a manual deployment outside the demo
for variable in "${!SMART_HOME_@}"; do
  unset "$variable"
done

mkdir -p target
work="$(mktemp -d "$root/target/local-demo.XXXXXXXX")"
server_pid=
node_pid=
panel_pid=

cleanup() {
  trap '' INT TERM
  for pid in "$panel_pid" "$node_pid" "$server_pid"; do
    if [[ -n "$pid" ]]; then
      kill "$pid" 2>/dev/null || true
    fi
  done
  for pid in "$panel_pid" "$node_pid" "$server_pid"; do
    if [[ -n "$pid" ]]; then
      wait "$pid" 2>/dev/null || true
    fi
  done
  cd "$root"
  rm -rf -- "$work"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

random_secret() {
  od -An -v -tx1 -N24 /dev/urandom | tr -d '[:space:]'
}

echo "Building the smart-home demo..."
mkdir -p "$work/classes" "$work/config/tls"
sources=()
while IFS= read -r -d '' source; do
  sources+=("$source")
done < <(find src/main/java -type f -name '*.java' -print0)
"$javac" --release 25 -encoding UTF-8 -d "$work/classes" "${sources[@]}"
cp -R src/main/resources/. "$work/classes/"
cp config/panel-users.properties "$work/config/"
cd "$work"

echo "Preparing a private local TLS certificate..."
SMART_HOME_DEMO_KEYSTORE_PASSWORD="$(random_secret)"
node_token="$(random_secret)"
panel_token="$(random_secret)"
export SMART_HOME_DEMO_KEYSTORE_PASSWORD
cat > config/local.properties <<EOF
SMART_HOME_HOST=127.0.0.1
SMART_HOME_PORT=$port
SMART_HOME_TLS_KEYSTORE_PASSWORD=$SMART_HOME_DEMO_KEYSTORE_PASSWORD
SMART_HOME_NODE_12_TOKEN=$node_token
SMART_HOME_PANEL_TOKEN=$panel_token
EOF
unset node_token panel_token

if ! {
  "$keytool" -genkeypair -alias smart-home-server -keyalg EC -groupname secp256r1 \
    -storetype PKCS12 -keystore config/tls/server.p12 -validity 365 \
    -dname "CN=Smart Home Local Demo" -ext "SAN=dns:localhost,ip:127.0.0.1" \
    -ext "EKU=serverAuth" -storepass:env SMART_HOME_DEMO_KEYSTORE_PASSWORD &&
  "$keytool" -exportcert -alias smart-home-server -keystore config/tls/server.p12 \
    -rfc -file config/tls/server.crt -storepass:env SMART_HOME_DEMO_KEYSTORE_PASSWORD
} > tls.log 2>&1; then
  cat tls.log >&2
  exit 1
fi
unset SMART_HOME_DEMO_KEYSTORE_PASSWORD

wait_for_start() {
  local label="$1" pid="$2" log="$3" expected="$4" attempt line
  for ((attempt = 0; attempt < 150; attempt++)); do
    while IFS= read -r line; do
      if [[ "$line" == "$expected"* ]]; then
        return 0
      fi
    done < "$log"
    if ! kill -0 "$pid" 2>/dev/null; then
      break
    fi
    sleep 0.1
  done
  echo "$label did not start." >&2
  cat "$log" >&2
  if [[ "$label" == "Server" ]]; then
    echo "If port $port is busy, run SMART_HOME_DEMO_PORT=5001 ./run-local.sh." >&2
  fi
  return 1
}

package=no.ntnu.idata2304.smarthome
touch server.log node.log
"$java" -cp classes "$package.server.ServerApplication" > server.log 2>&1 &
server_pid=$!
wait_for_start Server "$server_pid" server.log "Server started at "

"$java" -cp classes "$package.sensornode.SensorNodeApplication" > node.log 2>&1 &
node_pid=$!
wait_for_start "Sensor node" "$node_pid" node.log "Received response from server: READY;1"

echo "Ready. Try 'list' or 'read 12 1'. Type 'exit' to stop all three apps."
exec 3<&0
"$java" -cp classes "$package.controlpanel.ControlPanelApplication" <&3 3<&- &
panel_pid=$!
exec 3<&-
wait "$panel_pid"
